// Self-test / bring-up pattern: plays a script of VDPX bus operations from a ROM
// (generated by scripts/gen_selftest.py), so the board shows an animated
// picture with sound on HDMI without a Mega Drive attached.
//
// ROM word (24 bits): [23:22] op, [18:16] port, [15:0] data
//   op 0: WRITE port <- data
//   op 1: WAITVB  data = number of VBLANK starts to wait
//   op 2: JUMP    data = ROM address
//   op 3: FILL2   data = count; the next two ROM words hold v0, v1;
//                 writes DATA port v0, v1 alternately, count pairs
module vdpx_selftest #(
    parameter ROM_AW   = 12,
    parameter ROM_FILE = "selftest.hex"
) (
    input             clk,
    input             rst,
    input             enable,
    input             vblank,
    output reg        bus_cs,
    output reg        bus_we,
    output reg  [2:0] bus_addr,
    output reg [15:0] bus_wdata,
    input             bus_ack
);
    reg [23:0] rom [0:(1<<ROM_AW)-1];
    initial $readmemh(ROM_FILE, rom);

    reg [ROM_AW-1:0] pc;
    reg [23:0] w;
    always @(posedge clk) w <= rom[pc];

    localparam S_FETCH = 0, S_DEC = 1, S_BUS = 2, S_VB = 3, S_F0 = 4, S_F1 = 5, S_FW = 6, S_FV1 = 7;
    reg  [2:0] st;
    reg [15:0] n;
    reg [15:0] v0, v1;
    reg        vb_d, half;

    always @(posedge clk) begin
        vb_d <= vblank;
        if (rst || !enable) begin
            st <= S_FETCH; pc <= 0; bus_cs <= 1'b0;
        end else begin
            case (st)
            S_FETCH: st <= S_DEC;                       // ROM latency
            S_DEC: begin
                case (w[23:22])
                2'd0: begin
                    bus_cs <= 1'b1; bus_we <= 1'b1; bus_addr <= w[18:16]; bus_wdata <= w[15:0];
                    pc <= pc + 1'b1; st <= S_BUS;
                end
                2'd1: begin n <= w[15:0]; pc <= pc + 1'b1; st <= S_VB; end
                2'd2: begin pc <= w[ROM_AW-1:0]; st <= S_FETCH; end
                default: begin n <= w[15:0]; pc <= pc + 1'b1; st <= S_F0; end
                endcase
            end
            S_BUS: if (bus_ack) begin bus_cs <= 1'b0; st <= S_FETCH; end
            S_VB: begin
                if (n == 0) st <= S_FETCH;
                else if (vblank && !vb_d) n <= n - 16'd1;
            end
            S_F0: st <= S_F1;                           // wait for v0
            S_F1: begin v0 <= w[15:0]; pc <= pc + 1'b1; st <= S_FV1; end
            S_FV1: st <= S_FW;                          // wait for v1
            S_FW: begin
                if (!bus_cs) begin
                    if (half == 1'b0 && n == 0) begin
                        pc <= pc + 1'b1; st <= S_FETCH;     // done
                    end else begin
                        bus_cs <= 1'b1; bus_we <= 1'b1; bus_addr <= 3'd0;
                        bus_wdata <= half ? w[15:0] : v0;
                    end
                end else if (bus_ack) begin
                    bus_cs <= 1'b0;
                    if (half) half <= 1'b0;
                    else begin half <= 1'b1; n <= n - 16'd1; end
                end
            end
            default: st <= S_FETCH;
            endcase
            if (st == S_DEC) half <= 1'b0;
        end
    end
endmodule
